/**
 * Standard error format, mirroring the backend's AllExceptionsFilter.
 * Isomorphic: safe to import from server and client code.
 */

export interface FieldError {
  /** Full path in nested data, e.g. "options.0.text" */
  field: string;
  messages: string[];
}

export interface ApiErrorShape {
  statusCode: number;
  code: string;
  message: string;
  path: string;
  timestamp: string;
  fieldErrors?: FieldError[];
  details?: unknown;
}

export interface ApiSuccess<T> {
  success: true;
  data: T;
  message?: string;
}

/** Codes produced by the backend, plus the ones generated by the front-end itself. */
export const ErrorCode = {
  VALIDATION_ERROR: "VALIDATION_ERROR",
  UNAUTHORIZED: "UNAUTHORIZED",
  FORBIDDEN: "FORBIDDEN",
  NOT_FOUND: "NOT_FOUND",
  CONFLICT: "CONFLICT",
  TOO_MANY_REQUESTS: "TOO_MANY_REQUESTS",
  BAD_REQUEST: "BAD_REQUEST",
  INTERNAL_ERROR: "INTERNAL_ERROR",
  DUPLICATE_ENTRY: "DUPLICATE_ENTRY",
  INVALID_REFERENCE: "INVALID_REFERENCE",
  RELATION_VIOLATION: "RELATION_VIOLATION",
  DATABASE_ERROR: "DATABASE_ERROR",
  DATABASE_UNAVAILABLE: "DATABASE_UNAVAILABLE",
  PAYMENT_FAILED: "PAYMENT_FAILED",
  // generated on the front-end / BFF
  NETWORK_ERROR: "NETWORK_ERROR",
  INVALID_RESPONSE: "INVALID_RESPONSE",
  UNKNOWN_ERROR: "UNKNOWN_ERROR",
} as const;

export class ApiError extends Error implements ApiErrorShape {
  readonly statusCode: number;
  readonly code: string;
  readonly path: string;
  readonly timestamp: string;
  readonly fieldErrors?: FieldError[];
  readonly details?: unknown;

  constructor(shape: ApiErrorShape) {
    super(shape.message);
    this.name = "ApiError";
    this.statusCode = shape.statusCode;
    this.code = shape.code;
    this.path = shape.path;
    this.timestamp = shape.timestamp;
    this.fieldErrors = shape.fieldErrors;
    this.details = shape.details;
  }

  get isUnauthorized() {
    return this.statusCode === 401;
  }

  get isValidation() {
    return this.code === ErrorCode.VALIDATION_ERROR;
  }

  /** Plain, serializable form (safe to return from Server Actions / pass to client components). */
  toJSON(): ApiErrorShape {
    return {
      statusCode: this.statusCode,
      code: this.code,
      message: this.message,
      path: this.path,
      timestamp: this.timestamp,
      ...(this.fieldErrors ? { fieldErrors: this.fieldErrors } : {}),
      ...(this.details !== undefined ? { details: this.details } : {}),
    };
  }
}

export function isApiError(e: unknown): e is ApiError {
  return e instanceof ApiError;
}

export function isApiErrorShape(v: unknown): v is ApiErrorShape {
  if (typeof v !== "object" || v === null) return false;
  const o = v as Record<string, unknown>;
  return typeof o.statusCode === "number" && typeof o.code === "string" && typeof o.message === "string";
}

export function makeErrorShape(statusCode: number, code: string, message: string, path = ""): ApiErrorShape {
  return { statusCode, code, message, path, timestamp: new Date().toISOString() };
}

export function statusToCode(status: number): string {
  switch (status) {
    case 400:
      return ErrorCode.VALIDATION_ERROR;
    case 401:
      return ErrorCode.UNAUTHORIZED;
    case 403:
      return ErrorCode.FORBIDDEN;
    case 404:
      return ErrorCode.NOT_FOUND;
    case 409:
      return ErrorCode.CONFLICT;
    case 429:
      return ErrorCode.TOO_MANY_REQUESTS;
    default:
      return status >= 500 ? ErrorCode.INTERNAL_ERROR : ErrorCode.BAD_REQUEST;
  }
}

/**
 * Turns a failed Response into an ApiError. If the body is not in the standard
 * format (gateway HTML page, empty body, ...) a standard one is synthesized.
 */
export async function parseApiError(res: Response): Promise<ApiError> {
  let body: unknown = null;
  try {
    const text = await res.text();
    body = text ? JSON.parse(text) : null;
  } catch {
    body = null;
  }

  if (isApiErrorShape(body)) {
    return new ApiError({
      ...body,
      path: typeof body.path === "string" ? body.path : "",
      timestamp: typeof body.timestamp === "string" ? body.timestamp : new Date().toISOString(),
    });
  }

  let path = "";
  try {
    path = res.url ? new URL(res.url).pathname : "";
  } catch {
    /* ignore */
  }

  return new ApiError(
    makeErrorShape(res.status, statusToCode(res.status), res.statusText || "درخواست ناموفق بود.", path),
  );
}

export function networkError(path = ""): ApiError {
  return new ApiError(makeErrorShape(503, ErrorCode.NETWORK_ERROR, "ارتباط با سرور برقرار نشد.", path));
}

/** Any thrown value -> standard shape. */
export function toErrorShape(e: unknown): ApiErrorShape {
  if (isApiError(e)) return e.toJSON();
  if (isApiErrorShape(e)) return e;
  return makeErrorShape(
    500,
    ErrorCode.UNKNOWN_ERROR,
    e instanceof Error && e.message ? e.message : "خطای ناشناخته رخ داده است.",
  );
}

/** First message per field, handy for form libraries: { phone: "شماره تلفن معتبر نیست." } */
export function fieldErrorsToRecord(e: { fieldErrors?: FieldError[] } | null | undefined): Record<string, string> {
  const out: Record<string, string> = {};
  for (const fe of e?.fieldErrors ?? []) {
    if (fe.messages[0] && !(fe.field in out)) out[fe.field] = fe.messages[0];
  }
  return out;
}

export type ApiResult<T> = { data: T; error: null } | { data: null; error: ApiErrorShape };

/** Await a request without try/catch: `const { data, error } = await tryApi(serverFetch(...))`. */
export async function tryApi<T>(promise: Promise<T>): Promise<ApiResult<T>> {
  try {
    return { data: await promise, error: null };
  } catch (e) {
    return { data: null, error: toErrorShape(e) };
  }
}
